TRIGGERED_ABILITY.RESOLUTION_TIME_ACTION:
local answerDC = EffectDC():Make_Targets(0) local queryDC = EffectDC():Make_Chest(1) local player = EffectController() for i = 0, (4-1) do local card = player:Library_GetNth(i)
if card ~= nil then queryDC:Set_CardPtr(i, card)
if (card:GetCardType():Test(CARD_TYPE_LAND)) == false then queryDC:QueryUnselect_CardPtr(i) end else break end end player:ChooseItemFromDC( "CARD_QUERY_CHOOSE_LAND_TO_PUT_INTO_HAND", queryDC, answerDC, QUERY_FLAG_MAY)
